#include <iostream>
#include <string>
#include <sstream>

class TextDocumentAnalysis {
public:
    static std::string input(const std::string& str) {
        int length = str.length();
        bool insideParentheses = false;
        int wordCount = 0;
        int maxWordLength = 0;
        int currentWordLength = 0;
        for (int i = 0; i < length; i++) {
            char ch = str[i];
            if (ch == '(') {
                if (currentWordLength > 0) {
                    if (currentWordLength > maxWordLength) maxWordLength = currentWordLength;
                    currentWordLength = 0;
                }
                insideParentheses = true;
            } else if (ch == ')') {
                if (currentWordLength > 0) {
                    wordCount++;
                    currentWordLength = 0;
                }
                insideParentheses = false;
            } else if (ch == '_') {
                if (currentWordLength > 0) {
                    if (insideParentheses) {
                        wordCount++;
                    } else {
                        if (currentWordLength > maxWordLength) maxWordLength = currentWordLength;
                    }
                    currentWordLength = 0;
                }
            } else {
                currentWordLength++;
            }
        }
        if (currentWordLength > 0) {
            if (insideParentheses) {
                wordCount++;
            } else {
                if (currentWordLength > maxWordLength) maxWordLength = currentWordLength;
            }
        }
        return std::to_string(maxWordLength) + " " + std::to_string(wordCount);
    }
};

int main() {
    std::string line;
    while (std::getline(std::cin, line)) {
        // Read and discard the first line
        if (!std::getline(std::cin, line))
            break;
        std::cout << TextDocumentAnalysis::input(line) << std::endl;
    }
    return 0;
}

